// Extract key fields from Fireflies webhook payload
const body = $input.first().json.body || $input.first().json;

const meetingTitle = body.title || body.meeting_title || 'Untitled Meeting';
const transcript = body.transcript || body.summary?.overview || body.sentences?.map(s => `${s.speaker_name}: ${s.text}`).join('\n') || '';
const meetingDate = body.date || new Date().toISOString();
const attendees = body.attendees || body.participants || [];
const meetingId = body.id || body.meetingId || Date.now().toString();
const duration = body.duration || 'Unknown';

// Format attendee list
const attendeeList = Array.isArray(attendees) 
  ? attendees.map(a => a.displayName || a.name || a.email || a).join(', ')
  : String(attendees);

return [{
  json: {
    meetingTitle,
    transcript,
    meetingDate,
    attendeeList,
    meetingId,
    duration,
    rawBody: body
  }
}];

