// Parse Claude's JSON response
const claudeResponse = $input.first().json;
const content = claudeResponse.content?.[0]?.text || '{}';

let parsed;
try {
  // Strip any accidental markdown fences
  const clean = content.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    summary: 'Could not parse AI response',
    key_decisions: [],
    action_items: [],
    blockers: [],
    next_meeting_topics: []
  };
}

// Merge with meeting metadata from previous node
const prevData = $('Parse Fireflies Payload').first().json;

return [{
  json: {
    ...prevData,
    aiAnalysis: parsed,
    summary: parsed.summary,
    action_items: parsed.action_items || [],
    key_decisions: parsed.key_decisions || [],
    blockers: parsed.blockers || [],
    next_meeting_topics: parsed.next_meeting_topics || []
  }
}];

// Split action items into individual items for Trello card creation
const data = $input.first().json;
const actionItems = data.action_items || [];

if (actionItems.length === 0) {
  return [{ json: { ...data, task: 'Review meeting notes', owner: 'Unassigned', due_date: 'TBD', priority: 'Low', noActionItems: true } }];
}

return actionItems.map(item => ({
  json: {
    meetingTitle: data.meetingTitle,
    meetingDate: data.meetingDate,
    meetingId: data.meetingId,
    summary: data.summary,
    task: item.task,
    owner: item.owner,
    due_date: item.due_date,
    priority: item.priority,
    allData: data
  }
}));

// Build the Google Drive document content
const data = $('Parse AI Response').first().json;
const date = new Date(data.meetingDate).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const actionItemsText = (data.action_items || []).map((item, i) => 
  `${i+1}. ${item.task}\n   Owner: ${item.owner} | Due: ${item.due_date} | Priority: ${item.priority}`
).join('\n\n');

const decisionsText = (data.key_decisions || []).map((d, i) => `${i+1}. ${d}`).join('\n');
const blockersText = (data.blockers || []).map((b, i) => `${i+1}. ${b}`).join('\n') || 'None identified';
const nextTopicsText = (data.next_meeting_topics || []).map((t, i) => `${i+1}. ${t}`).join('\n') || 'TBD';

const docContent = `MEETING INTELLIGENCE REPORT
${'='.repeat(50)}

Meeting: ${data.meetingTitle}
Date: ${date}
Attendees: ${data.attendeeList}
Duration: ${data.duration}

${'─'.repeat(50)}
EXECUTIVE SUMMARY
${'─'.repeat(50)}
${data.summary}

${'─'.repeat(50)}
KEY DECISIONS
${'─'.repeat(50)}
${decisionsText || 'None recorded'}

${'─'.repeat(50)}
ACTION ITEMS (${(data.action_items || []).length} total)
${'─'.repeat(50)}
${actionItemsText || 'No action items identified'}

${'─'.repeat(50)}
BLOCKERS & RISKS
${'─'.repeat(50)}
${blockersText}

${'─'.repeat(50)}
NEXT MEETING TOPICS
${'─'.repeat(50)}
${nextTopicsText}

${'─'.repeat(50)}
FULL TRANSCRIPT
${'─'.repeat(50)}
${data.transcript}

---
Generated by Meeting Intelligence Pipeline | ${new Date().toISOString()}`;

return [{
  json: {
    ...data,
    docContent,
    fileName: `Meeting Notes - ${data.meetingTitle} - ${new Date(data.meetingDate).toLocaleDateString('en-US')}.txt`
  }
}];

// Final summary node - log what was created
const trelloResults = $('Create Trello Cards').all();
const driveResult = $('Save to Google Drive').first().json;
const meetingData = $('Parse AI Response').first().json;

const cardCount = trelloResults.length;
const driveLink = driveResult?.webViewLink || driveResult?.id || 'Check Google Drive';

console.log(`✅ Meeting Intelligence Pipeline Complete`);
console.log(`📋 Meeting: ${meetingData.meetingTitle}`);
console.log(`✅ Created ${cardCount} Trello cards`);
console.log(`📄 Google Drive doc saved`);

return [{
  json: {
    status: 'success',
    meeting: meetingData.meetingTitle,
    trelloCardsCreated: cardCount,
    googleDriveLink: driveLink,
    actionItems: meetingData.action_items,
    summary: meetingData.summary
  }
}];
